            if i < n and text[i] != SEP:
                raise ValueError(f"unexpected text after quoted value in {text!r}")
        else:
            start = i
            while i < n and text[i] != SEP:
                i += 1
            value = text[start:i].strip()
        if key in result:
            raise ValueError(f"duplicate key {key!r}")
        result[key] = value
        i += 1  # skip SEP (or move past the end)
    return result
